"""Collect the checksummed Member 4 deliverables package into ../deliverables/member4/ and write SUMMARY.md / results_summary.json from the saved JSON
evidence. Usage (from RecoveryAnalysis/): python3 -m recovery.collect_deliverables"""
import hashlib, json, os, shutil, subprocess
HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(os.path.dirname(HERE), "deliverables", "member4")
J = lambda p: json.load(open(os.path.join(HERE, p)))
MODELS = [("sparsebev", "SparseBEV"), ("streampetr", "StreamPETR"), ("bevformer", "BEVFormer")]
DUR = ["0.5", "1.0", "2.0"]
f = lambda x, n=3: "n/a" if x is None else f"{x:.{n}f}"
ci = lambda c: f"({f(c[0])}, {f(c[1])})"


def median_ci(md):
    lo = "not reached" if md["ci95_lower_not_reached"] else md["ci95"][0]; hi = "not reached" if md["ci95_upper_not_reached"] else md["ci95"][1]
    return f"[{lo}, {hi}], {md['n_replicates_unreached']}/{md['B']} replicates unreached"


def main():
    if os.path.exists(OUT):
        shutil.rmtree(OUT)
    os.makedirs(OUT)
    copy = ["README.md", "process.txt", "recovery", "artifacts/run_profile.sh", "artifacts/run_reproduction.sh", "artifacts/run_manifest.json", "artifacts/RUN_SUMMARIES.md",
            "artifacts/analysis", "artifacts/figures", "artifacts/profile", "artifacts/logs/status.txt", "artifacts/review_corrections.json",
            "artifacts/superseded_before_inspector_review2/analysis", "artifacts/superseded_before_inspector_review2/profile"]
    for fn in sorted(os.listdir(os.path.join(HERE, "artifacts/reproduction"))):
        if fn.endswith(".json"):
            copy.append(f"artifacts/reproduction/{fn}")
    for c in copy:
        s, d = os.path.join(HERE, c), os.path.join(OUT, c)
        if not os.path.exists(s):
            raise SystemExit(f"missing deliverable {c}")
        os.makedirs(os.path.dirname(d), exist_ok=True)
        (shutil.copytree(s, d, ignore=shutil.ignore_patterns("__pycache__")) if os.path.isdir(s) else shutil.copy2(s, d))
    rs, cs, man, tv = J("artifacts/analysis/recovery_summary.json"), J("artifacts/analysis/classes_sameobject.json"), J("artifacts/run_manifest.json"), J("artifacts/analysis/tables_verification.json")
    pr = {m: J(f"artifacts/profile/{m}.json") for m, _ in MODELS}
    repro = {fn: json.load(open(os.path.join(HERE, "artifacts/reproduction", fn))) for fn in sorted(os.listdir(os.path.join(HERE, "artifacts/reproduction"))) if fn.endswith(".json")}
    res = dict(bootstrap=rs["bootstrap"], rules=rs["rules"], aggregate=rs["aggregate"], events={m: {d: {k: v for k, v in e.items() if k != "cumulative_confirmed_onset_fraction_by_time_s"} for d, e in ev.items()} for m, ev in rs["events"].items()},
               common_events=rs["common_events"], pairwise=rs["pairwise"], same_object=cs["same_object"], profile=pr, reproduction=repro, tables_verification=tv,
               all_runs_ok=man["all_runs_ok"], n_runs_inspected=man["n_runs"], schedule_identical=man["val_schedule_identical_across_models"], crosscheck_member3=rs["crosscheck_member3_pooled_max_abs_diff"])
    json.dump(res, open(os.path.join(OUT, "results_summary.json"), "w"), indent=1)
    L = ["# Member 4 deliverables — run orchestration, recovery analysis with uncertainty, resource profile, figures\n",
         "Generated by `python3 -m recovery.collect_deliverables`. Method, interpretation and limitations: `README.md`; every run's provenance: `artifacts/RUN_SUMMARIES.md`.\n",
         f"## Integrity and verification\n* {man['n_runs']} run directories inspected: all pass = **{man['all_runs_ok']}**; validation schedule identical across the three projects = **{man['val_schedule_identical_across_models']}**.",
         f"* Independent rebuild of Member 3's per-scene tables from per-sample statuses: " + "; ".join(f"{m}: {v['mismatching_cells']}/{v['cells_compared']} mismatching cells" for m, v in tv["models"].items()) + f" (ALL_MATCH = {tv['ALL_MATCH']}); pooled estimates vs Member 3 summaries: max |diff| {rs['crosscheck_member3_pooled_max_abs_diff']}.",
         f"* Bootstrap: paired complete-scene resampling, B = {rs['bootstrap']['B']}, seed {rs['bootstrap']['seed']}, {rs['bootstrap']['interval']}; rules margin {rs['rules']['loss_margin']}, min objects {rs['rules']['min_gt']}.\n",
         "## Reproduction of saved results (pilot, 2 s outage re-run from the saved configuration)\n| model | samples | bit-identical predictions | max abs diff | audit records identical | checkpoint hash same | wall s |\n|---|---|---|---|---|---|---|"]
    for fn, r in repro.items():
        L.append(f"| {r['model']} | {r.get('n_samples')} | {r.get('bit_identical')} | {r.get('max_abs_pred_diff')} | {r.get('audit_records_identical')} | {r.get('ckpt_sha256_same')} | {r['wall_s']:.0f} |")
    L += ["\n## Aggregate recall loss L = R_clean − R_outage (pooled over 150 scenes; 95% paired scene-bootstrap intervals)\n| outage | model | loss during | relative loss | loss b0.0 | loss b0.5 | loss b1.0 | aggregate rule | aggregate onset (s) |\n|---|---|---|---|---|---|---|---|---|"]
    for d in DUR:
        for m, lab in MODELS:
            c, a = rs["curves"][m][d], rs["aggregate"][m][d]
            L.append(f"| {d} s | {lab} | {f(c['during']['loss'])} {ci(c['during']['loss_ci95'])} | {f(c['during']['relative_loss'], 2)} | {f(c['b0.0']['loss'])} {ci(c['b0.0']['loss_ci95'])} | {f(c['b0.5']['loss'])} | {f(c['b1.0']['loss'])} | "
                     f"{'detected' if a['aggregate_degradation_detected'] else 'not detected'} | {a['aggregate_recovery_onset_s']} |")
    L += ["\n## Per-event categories (150 events per model and duration)\n| outage | model | insufficient | no degradation | recovered at first bin | later recovery | no recovery (complete follow-up) | unconfirmed (incomplete follow-up) | damage rate (95% CI) | confirmed onset ≤ 4 s | complete follow-up: confirmed | median recovery (s) [95% interval; unreached replicates kept] |\n|---|---|---|---|---|---|---|---|---|---|---|---|"]
    for d in DUR:
        for m, lab in MODELS:
            e = rs["events"][m][d]; cc = list(e["category_counts"].values()); o = e["confirmed_onset_by_4s_among_damaged"]; cf = e["damaged_with_complete_followup"]; md = e["median_recovery_time_s"]
            L.append(f"| {d} s | {lab} | {' | '.join(map(str, cc))} | {f(e['damage_rate_among_sufficient']['value'], 2)} {ci(e['damage_rate_among_sufficient']['ci95'])} | {o['numerator']}/{o['denominator']} = {f(o['value'], 2)} | {cf['confirmed_onset']}/{cf['n']} | {(str(md['value']) + ' ' + median_ci(md)) if md['reached'] else 'not reached'} |")
    L += ["\nUnconfirmed events are right-censored by missing/insufficient follow-up bins (shared by all models), never read as permanent failure.\n",
          "## Common events (damaged in all three models) and paired differences\n| outage | common events | onset ≤ 4 s: SparseBEV / StreamPETR / BEVFormer | pooled-loss difference S−P (95% CI) | damage-rate difference S−P | S−B | P−B |\n|---|---|---|---|---|---|---|"]
    for d in DUR:
        ce, pw = rs["common_events"][d], rs["pairwise"][d]
        L.append(f"| {d} s | {ce['n_common_damaged_events']} | " + " / ".join(f(ce["per_model"][m]["confirmed_onset_by_4s"]["value"], 2) for m, _ in MODELS) +
                 f" | {f(pw['sparsebev_minus_streampetr']['pooled_loss_during_difference']['value'])} {ci(pw['sparsebev_minus_streampetr']['pooled_loss_during_difference']['ci95'])} | "
                 f"{f(pw['sparsebev_minus_streampetr']['damage_rate_difference']['value'])} {ci(pw['sparsebev_minus_streampetr']['damage_rate_difference']['ci95'])} | "
                 f"{f(pw['sparsebev_minus_bevformer']['damage_rate_difference']['value'])} {ci(pw['sparsebev_minus_bevformer']['damage_rate_difference']['ci95'])} | "
                 f"{f(pw['streampetr_minus_bevformer']['damage_rate_difference']['value'])} {ci(pw['streampetr_minus_bevformer']['damage_rate_difference']['ci95'])} |")
    L += ["\nDescriptive only: clean recall, thresholds, resolution, pretraining, query count and history differ across the three systems.\n",
          "## Same-object diagnostic (last during-outage sample → first STRICTLY LATER sample with a restored CAM_FRONT exposure)\nSame-sample (zero-time) and still-black pairs are unavailable, not recovery observations; the later observation is bin 0.0 for most events and bin 0.5 s for the rest (the primary bin assignment is unchanged).\n| outage | model | events with a valid pair (unavailable: same sample as bin 0.0) | continuing objects (clean detected at both) | missed during → detected later | 95% CI |\n|---|---|---|---|---|---|"]
    for d in DUR:
        for m, lab in MODELS:
            s = cs["same_object"][m][d]; r = s["recovered_among_missed_during"]
            ea = s['event_accounting']
            L.append(f"| {d} s | {lab} | {ea['events_with_last_during_and_later_restored']} of {ea['events_with_during_sample']} ({ea['events_unavailable_same_sample_as_bin0']} same-sample at bin 0.0, bin 0.0 reused: {ea['events_after_is_bin0']}, bin 0.5 s used: {ea['events_after_is_later_bin']}) | {s['counts']['continuing_clean_detected_both']} | {r['numerator']}/{r['denominator']} = {f(r['value'], 2)} | {ci(r['ci95'])} |")
    L += ["\n## Resource profile (RTX 3060 12 GB; batch 1; clean; 80 frames × 3 measured passes after a discarded warm-up pass; CUDA-synchronized)\n| model | median model latency ms | p95 ms | FPS | CPU decode+pipeline ms | end-to-end ms (paired per-frame decode + forward, single process) | peak allocated MB | peak reserved MB | parameters M |\n|---|---|---|---|---|---|---|---|---|"]
    for m, lab in MODELS:
        p = pr[m]; l = p["latency_ms"]
        L.append(f"| {lab} | {l['steady_median']:.1f} | {l['steady_p95']:.1f} | {p['fps_steady_median']:.1f} | {p['data_loading_cpu_ms']['median']:.0f} | {p['end_to_end_ms_paired_median']:.0f} | {p['peak_allocated_mb']:.0f} | {p['peak_reserved_mb']:.0f} | {p['n_parameters'] / 1e6:.1f} |")
    L += ["\n## Figures (`artifacts/figures/`)\n" + "\n".join(f"* `{fn}`" for fn in sorted(os.listdir(os.path.join(HERE, "artifacts/figures"))) if fn.endswith(".png")) + "\n* `qualitative/` — rule-selected events (SparseBEV timeline and three-model BEV comparison)"]
    open(os.path.join(OUT, "SUMMARY.md"), "w").write("\n".join(L) + "\n")
    files = sorted(os.path.relpath(os.path.join(r, fl), OUT) for r, _, fs in os.walk(OUT) for fl in fs)
    with open(os.path.join(OUT, "SHA256SUMS"), "w") as fh:
        for p in files:
            fh.write(f"{hashlib.sha256(open(os.path.join(OUT, p), 'rb').read()).hexdigest()}  {p}\n")
    print(len(files), "files ->", OUT); print(subprocess.run(["du", "-sh", OUT], capture_output=True, text=True).stdout)


if __name__ == "__main__":
    main()
